  "interfaces": [
    "CLI: `python3 -m unittest discover tests`",
    "Server: `python3 server.py` on localhost:8000",
    "Web: `http://localhost:8000`",
    "API: `GET /api/poll?name=<name>` and `POST /api/command?name=<name>`"
